            coin: coin.to_string(),
            side: side.to_string(),
            price: BigDecimal::from_str(price).unwrap(),
            size: BigDecimal::from_str(size).unwrap(),
            direction: if side == "B" {
                Some("Open Long".to_string())
            } else {
                Some("Close Long".to_string())
