            "hash": "0xfill1",
            "fee": "3.50",
            "feeToken": "USDC",
            "closedPnl": "0.0"
        });

        let raw_metadata = serde_json::json!({ "type": "fill", "data": fill_data });

        // V1: direct parse
        let v1_tx = spectraplex_core::models::Transaction {
            id: tx_id,
            user_id,
