    fn derived_materializers_are_v2() {
        let materializers: Vec<Box<dyn Materializer>> = vec![
            Box::new(SolanaDerivedLedgerMaterializer),
            Box::new(EvmDerivedLedgerMaterializer),
            Box::new(HyperliquidDerivedLedgerMaterializer),
