    }

    fn make_hl_funding(coin: &str, amount: &str) -> HlFundingPayment {
        HlFundingPayment {
            id: Uuid::new_v4(),
            raw_transaction_id: Some(Uuid::new_v4()),
            network: "hypercore-mainnet".to_string(),
            coin: coin.to_string(),
