        DatasetName::LedgerEntries
    }

    fn parser_version(&self) -> i32 {
        2
    }

    fn parser_hash(&self) -> &str {
        "sha256:evm_derived_ledger_v2_c3b5e8f2"
    }

    fn chain_family(&self) -> ChainFamily {
        ChainFamily::Evm
    }

    fn descriptor(&self) -> DatasetDescriptor {
