    #[test]
    fn chain_family_sql_roundtrip() {
        for cf in [
            ChainFamily::Solana,
            ChainFamily::Evm,
            ChainFamily::Hyperliquid,
        ] {
            let s = chain_family_to_sql(&cf);
            let back = sql_to_chain_family(s).unwrap();
            assert_eq!(cf, back, "roundtrip failed for {cf:?}");
        }
    }

