    ) -> anyhow::Result<Vec<IndexTarget>> {
        let rows = sqlx::query(
            "SELECT id, kind::text, network, chain_family::text, address, filter_spec, \
             mode::text, label, owner_id, created_at, updated_at \
             FROM index_targets WHERE network = $1 ORDER BY created_at",
