) -> Result<Json<Vec<Transaction>>, AppError> {
    validate_wallet(&wallet)?;
    check_wallet_allowed(&wallet, &state.allowed_wallets)?;
    validate_date_range(params.from, params.to)?;
    let limit = clamp_limit(params.limit);
