    let txs = state
        .repo
        .get_transactions_by_wallet_filtered(&wallet, limit, offset, params.from, params.to)
        .await
        .map_err(AppError::internal)?;
    Ok(Json(txs))
}

async fn get_ledger(
    State(state): State<Arc<AppState>>,
