        .await
        .map_err(AppError::internal)?
        .ok_or_else(|| AppError::not_found(format!("Target {} not found", target_id)))?;
    Ok(Json(target))
}

async fn list_networks(State(state): State<Arc<AppState>>) -> Result<Json<Vec<Network>>, AppError> {
