    State(state): State<Arc<AppState>>,
    Path(wallet): Path<String>,
    Query(params): Query<BalanceParams>,
) -> Result<Json<Vec<AssetBalance>>, AppError> {
    validate_wallet(&wallet)?;
    check_wallet_allowed(&wallet, &state.allowed_wallets)?;
