    completed_at: Option<chrono::DateTime<chrono::Utc>>,
    /// ID of the last ingestion run that contributed to the exported data.
    #[serde(skip_serializing_if = "Option::is_none")]
    last_ingestion_run_id: Option<Uuid>,
