    Query(params): Query<ForensicsParams>,
) -> Result<Json<ForensicsActivity>, AppError> {
    validate_date_range(params.time_start, params.time_end)?;

    let records = state
        .repo
        .export_wallet_ledger_records(
            params.target_id,
            params.network.as_deref(),
            params.time_start,
            params.time_end,
