                    started_at: None,
                    completed_at: None,
                    last_ingestion_run_id: None,
                },
                finished_at: Some(Instant::now()),
                data: Some(ExportData {
                    content_type: "application/x-ndjson",
                    body: b"{\"test\":1}\n{\"test\":2}\n".to_vec(),
                }),
            },
