            completeness_status: None,
            completeness_coverage: None,
            started_at: None,
            completed_at: None,
            last_ingestion_run_id: None,
        };
        let json = serde_json::to_value(&status).unwrap();
        let keys: Vec<&str> = json
            .as_object()
            .unwrap()
            .keys()
            .map(|k| k.as_str())
